import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Roadmaps — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"roadmaps-01-overview-and-concepts.md","filePath":"roadmaps-01-overview-and-concepts.md"}'),s={name:"roadmaps-01-overview-and-concepts.md"};function i(n,e,d,h,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="roadmaps-—-overview-concepts" tabindex="-1">Roadmaps — Overview &amp; Concepts <a class="header-anchor" href="#roadmaps-—-overview-concepts" aria-label="Permalink to &quot;Roadmaps — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-a-roadmap" tabindex="-1">What Is a Roadmap? <a class="header-anchor" href="#what-is-a-roadmap" aria-label="Permalink to &quot;What Is a Roadmap?&quot;">​</a></h2><p>A Roadmap in Lodestone is a narrative representation of a product plan, expressed as a hierarchy and visualized as a sunburst chart. It exists to answer two questions for your organization:</p><ul><li><strong>WHAT</strong> are we building?</li><li><strong>WHY</strong> are we building these things instead of others?</li></ul><p>Lodestone Roadmaps are not timelines, Gantt charts, or task boards. They don&#39;t show dates or delivery schedules — that&#39;s what Releases are for. A Roadmap explains intent and priorities; a Release tracks progress and timing.</p><hr><h2 id="the-sunburst-chart" tabindex="-1">The Sunburst Chart <a class="header-anchor" href="#the-sunburst-chart" aria-label="Permalink to &quot;The Sunburst Chart&quot;">​</a></h2><p>The sunburst is Lodestone&#39;s signature visualization. It&#39;s best understood as a traditional org chart hierarchy curled into a circle:</p><ul><li>The <strong>center ring</strong> holds the highest-level items — your goals, themes, or top-level groupings</li><li>Each <strong>outward ring</strong> represents a deeper level of detail</li><li><strong>Segments nest within their parent segments</strong>, so the visual hierarchy mirrors your planning hierarchy</li></ul><p>The result is a single image that makes it immediately clear how tactical work connects to strategic intent — something a swim lane or spreadsheet can&#39;t do at a glance.</p><p>The sunburst updates in real time as you add or rearrange items, so you always see your plan taking shape as you build it.</p><hr><h2 id="what-makes-lodestone-roadmaps-different" tabindex="-1">What Makes Lodestone Roadmaps Different <a class="header-anchor" href="#what-makes-lodestone-roadmaps-different" aria-label="Permalink to &quot;What Makes Lodestone Roadmaps Different&quot;">​</a></h2><p>Two things set Lodestone Roadmaps apart from most roadmap tools:</p><h3 id="_1-hierarchy-over-timelines" tabindex="-1">1. Hierarchy over timelines <a class="header-anchor" href="#_1-hierarchy-over-timelines" aria-label="Permalink to &quot;1. Hierarchy over timelines&quot;">​</a></h3><p>Most roadmap tools organize by time — quarters, swimlanes, milestones. Lodestone organizes by meaning. The hierarchy in the sunburst shows how your work rolls up, not when it ships.</p><h3 id="_2-built-to-be-presented" tabindex="-1">2. Built to be presented <a class="header-anchor" href="#_2-built-to-be-presented" aria-label="Permalink to &quot;2. Built to be presented&quot;">​</a></h3><p>When you export a Roadmap as a full PowerPoint presentation, Lodestone generates a slide for every item at every level of the hierarchy — walking through the plan section by section, telling a coherent story. The roadmap isn&#39;t just visualized; it&#39;s packaged for an audience.</p><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h3><p>Roadmap items are organized in a parent-child structure. A parent item groups its children; children inherit their parent&#39;s context. There is no limit to how many levels deep you can nest — the sunburst adds rings as you go.</p><h3 id="items-and-features" tabindex="-1">Items and Features <a class="header-anchor" href="#items-and-features" aria-label="Permalink to &quot;Items and Features&quot;">​</a></h3><p>Every item you add to a Roadmap starts life as a Feature. When an item becomes a parent (i.e. something is nested beneath it), it transforms into a grouping label — it disappears from the Feature backlog and becomes a tag applied to its children. Child Features inherit their parent and grandparent items as tags, preserving hierarchy context across the platform.</p><h3 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to &quot;Color&quot;">​</a></h3><p>Each Roadmap item has a color, which you set. Colors propagate from parent to child, visually grouping related work in the sunburst. Color is a storytelling tool — it helps audiences see which segments belong together at a glance.</p><h3 id="contextual-sizing-and-coloring" tabindex="-1">Contextual Sizing and Coloring <a class="header-anchor" href="#contextual-sizing-and-coloring" aria-label="Permalink to &quot;Contextual Sizing and Coloring&quot;">​</a></h3><p>Beyond the structural hierarchy and color families, you can layer additional meaning onto the outermost ring (where Features sit) by sizing and coloring segments based on their Value or Effort scores. This makes tradeoffs visible without changing the underlying structure.</p><h3 id="deprioritized-items" tabindex="-1">Deprioritized Items <a class="header-anchor" href="#deprioritized-items" aria-label="Permalink to &quot;Deprioritized Items&quot;">​</a></h3><p>Roadmaps are expected to evolve. Rather than deleting items that don&#39;t make the cut, Lodestone encourages keeping deprioritized items visible in a separate section. This tells a richer story — not just what you&#39;re building, but what you&#39;ve consciously decided not to build right now.</p><hr><h2 id="how-roadmaps-relate-to-the-rest-of-lodestone" tabindex="-1">How Roadmaps Relate to the Rest of Lodestone <a class="header-anchor" href="#how-roadmaps-relate-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Roadmaps Relate to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Features</td><td>Features are the building blocks of every Roadmap. The same Feature can appear in multiple Roadmaps simultaneously.</td></tr><tr><td>Releases</td><td>Roadmaps answer WHAT and WHY. Releases answer WHEN. A common pattern is to define intent in a Roadmap and track execution in a Release.</td></tr><tr><td>Strategy</td><td>Roadmaps represent near-to-medium term plans. Strategy covers longer-horizon investment decisions and tradeoffs.</td></tr><tr><td>Documents</td><td>Opportunity Canvases for Features in a Roadmap are automatically collected and appended to the full PPT export.</td></tr></tbody></table><hr><h2 id="who-can-create-roadmaps" tabindex="-1">Who Can Create Roadmaps <a class="header-anchor" href="#who-can-create-roadmaps" aria-label="Permalink to &quot;Who Can Create Roadmaps&quot;">​</a></h2><p>Any workspace member can create a Roadmap — it is not restricted to admins. A workspace can have multiple Roadmaps, and there is no limit on how many you create.</p><hr><h2 id="archiving-roadmaps" tabindex="-1">Archiving Roadmaps <a class="header-anchor" href="#archiving-roadmaps" aria-label="Permalink to &quot;Archiving Roadmaps&quot;">​</a></h2><p>Roadmaps can be archived when they&#39;re no longer active. Archiving a Roadmap has no impact on the Features within it — they remain in the Feature backlog as normal. Archived Roadmaps are no longer shown in the active list but are preserved for reference.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for building, editing, and exporting Roadmaps.</em></p>',43)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
